<?php
namespace App\Http\Controllers;
use App\Models\HrEmployeeRequest; use App\Services\HrAccess; use Illuminate\Http\Request;
class HrEmployeeRequestController extends AccountBaseController { public function index(){ $this->own=HrEmployeeRequest::where('employee_id',user()->id)->latest()->get(); $this->pending=HrEmployeeRequest::with('employee')->where('status','pending')->latest()->get()->filter(fn($r)=>in_array(user()->permission('edit_employees'),['all','branch'],true)&&HrAccess::canAccessEmployeeBranch(user(),$r->employee,'employee_requests')); return view('hr-employee-requests.index',$this->data);} public function store(Request $request){$data=$request->validate(['type'=>'required|in:personal_details,document_upload,employment_letter,salary_advance,asset_issue,asset_return,asset_damage','details'=>'required|string|max:4000']);HrEmployeeRequest::create($data+['company_id'=>user()->company_id,'employee_id'=>user()->id]);return back()->with('success','Request submitted.');} public function review(Request $request,HrEmployeeRequest $employeeRequest){$data=$request->validate(['status'=>'required|in:approved,rejected','review_note'=>'nullable|string|max:2000']);abort_403(!in_array(user()->permission('edit_employees'),['all','branch'],true)||!HrAccess::canAccessEmployeeBranch(user(),$employeeRequest->employee,'employee_requests'));$employeeRequest->update($data+['reviewed_by'=>user()->id,'reviewed_at'=>now()]);return back()->with('success','Request reviewed.');}}
